/* parcellscope website: the rotating 3D brain in the hero.
   Drag to turn it any way, double-click to reset. Pauses when off screen or in a background tab. */
(function(){
"use strict";
/* ---------- 3D brain (colours read from the theme) ---------- */
const RM=matchMedia('(prefers-reduced-motion: reduce)').matches;
let RAF=0,DRAW=null,ANG=.5,TILT=.28,DRAG=null,VA=0,VB=0;
/* Brain shape: outer surface of FSL's MNI152 1 mm template (every surface voxel at 1 mm, sulci included), and Harvard-Oxford
   subcortical structures (1 mm: every boundary voxel plus some of the inside), in mm about (0,-17,19) - the same template as Combining Regions' 3D view.
   Public templates only; no participant data. */
const dec=b=>{const s=atob(b),a=new Int8Array(s.length);for(let i=0;i<s.length;i++)a[i]=s.charCodeAt(i)<<24>>24;return a};
const SH=dec("");
const SB=dec("");
/* centroids [x,y,z,colour]: thalamus L R, caudate, putamen, pallidum, hippocampus, amygdala, accumbens */
const CL=[[-10, -2, -13, 1], [11, -1, -12, 1], [-13, 27, -9, 2], [13, 27, -8, 2], [-25, 18, -19, 2], [25, 19, -19, 2], [-19, 12, -20, 4], [20, 13, -20, 4], [-25, -5, -33, 3], [26, -3, -34, 3], [-23, 12, -37, 4], [23, 13, -37, 4], [-10, 29, -26, 2], [9, 29, -25, 2]];
const ED=[[0,1],[0,8],[1,9],[0,2],[1,3],[2,4],[3,5],[8,10],[9,11],[12,13],[4,8],[5,9],[6,0],[7,1]];
function brain3d(cv,site){
 const cs=getComputedStyle(site),col={1:cs.getPropertyValue('--c1').trim(),2:cs.getPropertyValue('--c2').trim(),3:cs.getPropertyValue('--c3').trim(),4:cs.getPropertyValue('--c4').trim()},
  dot=cs.getPropertyValue('--dot').trim(),spark=cs.getPropertyValue('--spark').trim(),light=cs.colorScheme==='light';
 const hx=/^#([0-9a-f]{6})$/i.exec(dot),RGB=hx?[0,2,4].map(i=>parseInt(hx[1].substr(i,2),16)):[150,175,210];
 const nS=SH.length/3,ob=document.createElement('canvas'),of=document.createElement('canvas'),oc=document.createElement('canvas');
 let last=0,AB=null,AF=null,IB=null,IF=null,bw=0,bh=0;
 /* drag turns it any way: sideways = spin, up/down = tip; it keeps some momentum when let go */
 cv.addEventListener('pointerdown',e=>{DRAG={x:e.clientX,y:e.clientY};VA=VB=0;cv.style.cursor='grabbing';try{cv.setPointerCapture(e.pointerId)}catch(_){}});
 cv.addEventListener('pointermove',e=>{if(!DRAG)return;const dx=e.clientX-DRAG.x,dy=e.clientY-DRAG.y;DRAG={x:e.clientX,y:e.clientY};
  VA=dx*.008;VB=dy*.008;ANG+=VA;TILT+=VB;if(RM)draw(last)});
 const up=()=>{DRAG=null;cv.style.cursor=''};cv.addEventListener('pointerup',up);cv.addEventListener('pointercancel',up);
 cv.addEventListener('dblclick',()=>{ANG=.5;TILT=.28;VA=VB=0;if(RM)draw(last)});
 function toImg(A,I){const d=I.data;for(let i=0,j=0;i<A.length;i++,j+=4){const v=A[i];if(v<=0){d[j+3]=0;continue}d[j]=RGB[0];d[j+1]=RGB[1];d[j+2]=RGB[2];d[j+3]=v>=1?255:v*255}}
 function draw(t){last=t;const w=cv.clientWidth,h=cv.clientHeight,d=Math.min(2,window.devicePixelRatio||1);if(!w||!h)return;
  if(cv.width!==Math.round(w*d)||cv.height!==Math.round(h*d)){cv.width=Math.round(w*d);cv.height=Math.round(h*d)}
  const x=cv.getContext('2d');x.setTransform(d,0,0,d,0,0);x.clearRect(0,0,w,h);
  if(!RM&&!DRAG){ANG+=.0035+VA;TILT+=VB;VA*=.95;VB*=.95}
  const K=Math.min(w,h)/190,cx=w/2,cy=h/2,ca=Math.cos(ANG),sa=Math.sin(ANG),ct=Math.cos(TILT),st=Math.sin(TILT);
  const pr=(X,Y,Z)=>{const x1=X*ca-Y*sa,y1=X*sa+Y*ca,z2=Z*ct-y1*st,dp=Z*st+y1*ct,s=420/(420-dp);return[cx+x1*K*s,cy-z2*K*s,dp,s]};
  /* surface: ~190k points splatted into two density buffers (behind / in front of the centre), at most 3 px per mm */
  const D=K*d,q=Math.max(1,D/3),bk=d/q,W2=Math.ceil(w*bk),H2=Math.ceil(h*bk),sp=D/q>2?2:1;
  if(W2!==bw||H2!==bh){bw=ob.width=of.width=W2;bh=ob.height=of.height=H2;AB=new Float32Array(bw*bh);AF=new Float32Array(bw*bh);
   IB=ob.getContext('2d').createImageData(bw,bh);IF=of.getContext('2d').createImageData(bw,bh)}else{AB.fill(0);AF.fill(0)}
  const kk=K*bk,bx=cx*bk,by=cy*bk,wb=light?1.6:1,lim=bw-sp,limy=bh-sp;
  for(let i=0,n=SH.length;i<n;i+=3){const X=SH[i],Y=SH[i+1],Z=SH[i+2],x1=X*ca-Y*sa,y1=X*sa+Y*ca,z2=Z*ct-y1*st,dp=Z*st+y1*ct,s=420/(420-dp);
   const px=(bx+x1*kk*s)|0,py=(by-z2*kk*s)|0;if(px<0||py<0||px>lim||py>limy)continue;
   let A,v;if(dp>0){A=AF;v=(.10+.22*dp/95)*wb}else{A=AB;v=(.03+.09*(1+dp/95))*wb}
   const o=py*bw+px;A[o]+=v;if(sp>1){A[o+1]+=v;A[o+bw]+=v;A[o+bw+1]+=v}}
  toImg(AB,IB);ob.getContext('2d').putImageData(IB,0,0);toImg(AF,IF);of.getContext('2d').putImageData(IF,0,0);
  x.imageSmoothingEnabled=true;x.drawImage(ob,0,0,w,h);
  const C2=CL.map(c=>pr(c[0],c[1],c[2]));x.lineWidth=1.3;
  ED.forEach(([i,j],k)=>{const a=C2[i],b=C2[j],pl=.5+.5*Math.sin(t/650+k);x.strokeStyle=col[CL[i][3]];x.globalAlpha=.25+.5*pl;x.beginPath();x.moveTo(a[0],a[1]);x.lineTo(b[0],b[1]);x.stroke();
   const f=((t/1700)+k*.137)%1;x.globalAlpha=.95;x.fillStyle=spark;x.beginPath();x.arc(a[0]+(b[0]-a[0])*f,a[1]+(b[1]-a[1])*f,1.8,0,7);x.fill()});
  /* structures: fine 1 mm points per colour into their own layer, drawn once blurred (glow) and once sharp */
  if(oc.width!==cv.width||oc.height!==cv.height){oc.width=cv.width;oc.height=cv.height}
  const y=oc.getContext('2d');y.setTransform(d,0,0,d,0,0);y.clearRect(0,0,w,h);const r=Math.max(.8,K*.95);
  for(const c of[1,2,3,4]){y.fillStyle=col[c];y.globalAlpha=.55;y.beginPath();
   for(let i=0;i<SB.length;i+=4){if(SB[i+3]!==c)continue;const q2=pr(SB[i],SB[i+1],SB[i+2]);y.rect(q2[0],q2[1],r,r)}y.fill()}
  x.save();x.globalAlpha=light?.45:.8;x.filter='blur('+Math.round(K*3)+'px)';x.drawImage(oc,0,0,w,h);x.restore();
  x.globalAlpha=1;x.drawImage(oc,0,0,w,h);
  x.globalAlpha=1;x.drawImage(of,0,0,w,h)}
 return draw;
}

const cv=document.querySelector('[data-anim="brain3d"]'),site=document.querySelector('.site');
if(!cv||!site)return;
const draw=brain3d(cv,site);
let on=true,vis=true;
const loop=t=>{draw(t);if(on&&vis&&!RM)RAF=requestAnimationFrame(loop)};
const start=()=>{cancelAnimationFrame(RAF);if(RM)draw(0);else RAF=requestAnimationFrame(loop)};
if('IntersectionObserver' in window)new IntersectionObserver(es=>{on=es[0].isIntersecting;if(on)start()}).observe(cv);
document.addEventListener('visibilitychange',()=>{vis=!document.hidden;if(vis)start()});
let rt;window.addEventListener('resize',()=>{clearTimeout(rt);rt=setTimeout(()=>{if(RM)draw(0)},120)});
start();
})();
